-- NEWS HUB editorial refresh: replace demo copy for existing 8 article rows.
-- No new tables, no new accounts, no duplicate inserts. Keeps each row's original published_at.
-- Run once after backing up the production database.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;

UPDATE articles SET
  category_id = (SELECT id FROM categories WHERE slug='thoi-su' LIMIT 1),
  title = 'Việt Nam nhận vai trò chủ nhà APEC 2027: Ba ưu tiên cho kỳ hội nghị tới',
  summary = 'Sau lễ chuyển giao tại Thâm Quyến ngày 19/11, Việt Nam bắt đầu chuẩn bị cho năm APEC 2027. Các đề xuất tập trung vào thương mại mở, động lực tăng trưởng mới và đối thoại trong khu vực.',
  content = '<p>Ngày 19/11/2026, tại Thâm Quyến (Trung Quốc), Tổng Bí thư, Chủ tịch nước Tô Lâm chính thức tiếp nhận vai trò chủ nhà APEC 2027 từ Chủ tịch Trung Quốc Tập Cận Bình. Lễ chuyển giao diễn ra trong khuôn khổ Hội nghị các nhà lãnh đạo kinh tế APEC lần thứ 33, với sự chứng kiến của đại diện các nền kinh tế thành viên.</p><p>Việt Nam sẽ lần thứ ba đăng cai APEC, sau các năm 2006 và 2017. Năm chủ nhà không chỉ là chuỗi sự kiện cấp cao: nước đăng cai còn phối hợp chương trình nghị sự, tổ chức các cuộc họp bộ trưởng và quan chức, đồng thời tạo không gian để doanh nghiệp và tổ chức trong khu vực trao đổi về thương mại, đầu tư và những vấn đề chung.</p><h2>Ba hướng hợp tác được đề xuất</h2><p>Tại hội nghị, Việt Nam nêu ba hướng ưu tiên: duy trì thương mại và đầu tư mở; thúc đẩy các động lực tăng trưởng mới, trong đó có đổi mới sáng tạo và chuyển đổi số; và tăng cường đối thoại, xây dựng lòng tin để giữ ổn định khu vực châu Á – Thái Bình Dương. Đây là những đề xuất cho thảo luận chung, không phải cam kết đã được triển khai.</p><p>Thách thức của năm APEC 2027 là chuyển các chủ đề lớn thành sáng kiến có thể theo dõi: thuận lợi hóa thương mại, kết nối chuỗi cung ứng, hỗ trợ doanh nghiệp vừa và nhỏ, phát triển kỹ năng số và tăng khả năng ứng phó trước biến động kinh tế. Kết quả sẽ phụ thuộc vào đồng thuận giữa 21 nền kinh tế thành viên.</p><p>Với Việt Nam, công tác chuẩn bị còn là cơ hội giới thiệu năng lực tổ chức, môi trường đầu tư và các địa phương đăng cai hoạt động. Những nội dung cụ thể về lịch họp, ưu tiên chính thức và chương trình dành cho doanh nghiệp sẽ cần được công bố trong quá trình chuẩn bị.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://english.vov.vn/en/politics/diplomacy/vietnam-proposes-new-directions-for-apec-cooperation-in-a-changing-world-post1351522.vov">VOV – Vietnam proposes new directions for APEC cooperation</a> · <a href="https://en.vietnamplus.vn/">VietnamPlus / Thông tấn xã Việt Nam</a>. Nội dung được NEWS HUB biên tập và diễn giải độc lập.</p></blockquote>',
  thumbnail = 'seed_world.jpg', status='published', is_featured=1
WHERE slug='sample-01-thoi-su';

UPDATE articles SET
  category_id = (SELECT id FROM categories WHERE slug='the-gioi' LIMIT 1),
  title = 'Việt Nam – Mỹ trao đổi về thương mại và đầu tư bên lề APEC 2026',
  summary = 'Cuộc gặp giữa lãnh đạo Việt Nam và Tổng thống Mỹ tại Thâm Quyến đề cập quan hệ Đối tác chiến lược toàn diện, hợp tác kinh tế và sự ủng hộ dành cho vai trò chủ nhà APEC 2027 của Việt Nam.',
  content = '<p>Ngày 19/11/2026, bên lề Tuần lễ Cấp cao APEC tại Thâm Quyến, Tổng Bí thư, Chủ tịch nước Tô Lâm gặp Tổng thống Mỹ Donald Trump. Theo thông tin được công bố, hai bên trao đổi về quan hệ song phương và các định hướng hợp tác trong thời gian tới.</p><p>Phía Việt Nam đề nghị tiếp tục tăng cường trao đổi, phối hợp để triển khai khuôn khổ Đối tác chiến lược toàn diện. Các nội dung được nêu gồm thúc đẩy quan hệ kinh tế, thương mại và đầu tư theo hướng ổn định, cân bằng, bền vững, cùng xử lý những vấn đề hai bên quan tâm.</p><p>Cuộc gặp cũng gắn với công tác chuẩn bị APEC 2027. Lãnh đạo Việt Nam mời Tổng thống Mỹ thăm Việt Nam và tham dự Tuần lễ Cấp cao tại Phú Quốc; phía Mỹ bày tỏ ủng hộ Việt Nam đảm nhiệm vai trò chủ nhà APEC năm tới.</p><h2>Điều cần theo dõi</h2><p>Thông tin sau cuộc gặp cho thấy định hướng và thiện chí chính trị, chưa phải một thỏa thuận thương mại mới với chỉ tiêu hay thời hạn cụ thể. Những bước tiếp theo cần được đánh giá qua các cuộc làm việc giữa cơ quan chức năng, doanh nghiệp và việc triển khai các cam kết đã có.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://e.vnexpress.net/news/news/politics/vietnam-s-top-leader-to-lam-meets-us-president-trump-on-apec-sidelines-in-shenzhen-5146791.html">VnExpress International – Vietnam’s top leader meets US President Trump</a>. Nội dung được NEWS HUB tóm lược bằng lời riêng.</p></blockquote>',
  thumbnail = 'seed_lifestyle.jpg', status='published', is_featured=0
WHERE slug='sample-05-the-gioi';

UPDATE articles SET
  category_id = (SELECT id FROM categories WHERE slug='kinh-doanh' LIMIT 1),
  title = 'Việt Nam đề xuất nguồn cung gạo dài hạn, ổn định cho Philippines',
  summary = 'Đề xuất được nêu trong cuộc gặp giữa lãnh đạo hai nước bên lề APEC. Hiện chưa có thông tin công bố về sản lượng, thời hạn hay điều khoản của thỏa thuận.',
  content = '<p>Trong cuộc gặp với Tổng thống Philippines Ferdinand Marcos Jr. bên lề APEC tại Thâm Quyến ngày 19/11/2026, lãnh đạo Việt Nam cho biết Việt Nam sẵn sàng bảo đảm nguồn cung gạo ổn định, dài hạn cho Philippines. Reuters dẫn thông tin từ cuộc gặp và cho biết Philippines là một trong những thị trường nhập khẩu gạo quan trọng của Việt Nam.</p><p>Đề xuất này được đặt trong bối cảnh an ninh lương thực tiếp tục là vấn đề quan trọng với nhiều nền kinh tế. Với nước nhập khẩu, nguồn cung có tính ổn định giúp cơ quan điều hành và doanh nghiệp chủ động hơn trong kế hoạch mua hàng. Với nước xuất khẩu, hợp tác dài hạn có thể tạo đầu ra dễ dự báo hơn cho doanh nghiệp và người sản xuất.</p><h2>Chưa có điều khoản cụ thể</h2><p>Thông tin công khai hiện chưa nêu sản lượng, lịch giao hàng, mức giá, thời hạn hoặc cơ chế thực hiện. Vì vậy, đề xuất ở cấp lãnh đạo chưa thể được xem là hợp đồng cung ứng đã hoàn tất. Các điều kiện thương mại, kiểm dịch, logistics và biến động mùa vụ vẫn cần được các bên làm rõ.</p><p>Diễn biến tiếp theo đáng chú ý là việc cơ quan chuyên môn và doanh nghiệp hai nước có xây dựng được cơ chế phối hợp ổn định hay không. Một thỏa thuận hiệu quả cần bảo đảm lợi ích của người trồng lúa, doanh nghiệp xuất khẩu và người tiêu dùng tại thị trường nhập khẩu.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://www.reuters.com/markets/commodities/vietnams-lam-offers-long-term-rice-supply-philippines-apec-talks-2026-11-19/">Reuters – Vietnam offers long-term rice supply to the Philippines</a>. NEWS HUB diễn giải lại; Reuters chưa công bố sản lượng hoặc điều khoản.</p></blockquote>',
  thumbnail = 'seed_business.jpg', status='published', is_featured=0
WHERE slug='sample-07-tai-chinh';

UPDATE articles SET
  category_id = (SELECT id FROM categories WHERE slug='tri-tue-nhan-tao' LIMIT 1),
  title = 'ILO: Khoảng 11,5 triệu việc làm tại Việt Nam có thể chịu tác động của AI tạo sinh',
  summary = 'Ước tính tương đương 20,8% tổng việc làm. “Chịu tác động” không đồng nghĩa chắc chắn mất việc; kết quả còn phụ thuộc tính chất công việc, cách doanh nghiệp ứng dụng công nghệ và cơ hội nâng kỹ năng.',
  content = '<p>Theo thông tin Nhân Dân đăng ngày 19/11/2026, ước tính của Tổ chức Lao động Quốc tế (ILO) cho thấy khoảng 11,5 triệu việc làm tại Việt Nam, tương đương 20,8% tổng số việc làm, có thể chịu tác động của trí tuệ nhân tạo tạo sinh. Con số phản ánh mức độ các nhiệm vụ trong công việc có khả năng tiếp xúc với công nghệ, không phải dự báo rằng từng ấy người sẽ bị thay thế.</p><p>AI có thể hỗ trợ các công việc lặp lại như phân loại thông tin, soạn bản nháp, xử lý dữ liệu hoặc hỗ trợ chăm sóc khách hàng. Tuy vậy, nhiều nghề còn đòi hỏi phán đoán, trách nhiệm, giao tiếp trực tiếp và hiểu bối cảnh — những phần việc khó có thể được đánh giá chỉ bằng khả năng tự động hóa một tác vụ riêng lẻ.</p><h2>Khả năng thích ứng mới là yếu tố quyết định</h2><p>Nhân Dân dẫn lưu ý của ILO rằng mức độ ảnh hưởng phụ thuộc vào bản chất từng công việc, khả năng ứng dụng công nghệ của doanh nghiệp và kỹ năng của người lao động. Bài viết cũng nêu phụ nữ hiện diện nhiều hơn trong một số nhóm nghề có mức độ tiếp xúc cao với AI, vì vậy chính sách đào tạo và hỗ trợ cần tính đến khác biệt giữa các nhóm lao động.</p><p>Đối với doanh nghiệp, mua công cụ AI chưa tự động tạo ra năng suất cao hơn. Quy trình làm việc, chất lượng dữ liệu, kiểm soát đầu ra và đào tạo nhân viên đều cần được cải thiện song song. Với người lao động, kỹ năng số, khả năng kiểm chứng thông tin và chuyên môn nền tảng sẽ giúp sử dụng công cụ hiệu quả hơn.</p><p>Thông điệp quan trọng không phải là chạy đua với máy móc, mà là chuẩn bị cho sự thay đổi của nhiệm vụ trong từng nghề. Đào tạo lại, bảo vệ quyền lợi người lao động và tạo điều kiện để mọi người tham gia vào quá trình chuyển đổi sẽ quyết định lợi ích của AI được phân bổ ra sao.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://en.nhandan.vn/around-115-million-jobs-in-viet-nam-could-be-affected-by-ai-post169367.html">Nhân Dân – Around 11.5 million jobs in Viet Nam could be affected by AI</a>. Nội dung được NEWS HUB tổng hợp và diễn giải độc lập.</p></blockquote>',
  thumbnail = 'seed_work.jpg', status='published', is_featured=1
WHERE slug='sample-03-moi-truong';

UPDATE articles SET
  category_id = (SELECT id FROM categories WHERE slug='cong-nghe' LIMIT 1),
  title = 'Bản đồ doanh nghiệp công nghệ số Việt Nam 2026 bao phủ 11 lĩnh vực',
  summary = 'VINASA công bố bản đồ trực tuyến với 108 vị trí doanh nghiệp trong 11 lĩnh vực; 51 danh hiệu Top 10 được trao cho 33 doanh nghiệp.',
  content = '<p>Ngày 19/11/2026, Hiệp hội Phần mềm và Dịch vụ Công nghệ thông tin Việt Nam (VINASA) giới thiệu Bản đồ doanh nghiệp công nghệ số Việt Nam 2026 và công bố các danh hiệu Top 10 doanh nghiệp công nghệ số. Theo VietnamPlus, chương trình năm nay trao 51 danh hiệu cho 33 doanh nghiệp thuộc 11 lĩnh vực.</p><p>Bản đồ trực tuyến được thiết kế để khách hàng, đối tác và nhà đầu tư tra cứu doanh nghiệp theo nhóm hoạt động. Phiên bản 2026 có 108 vị trí doanh nghiệp trong 11 lĩnh vực. Việc đưa thông tin lên một nền tảng tra cứu giúp người dùng có điểm bắt đầu khi tìm nhà cung cấp hoặc đối tác công nghệ trong nước.</p><h2>Danh bạ được cập nhật trong năm</h2><p>Một thay đổi được giới thiệu là cơ chế tiếp nhận, xác minh và cập nhật hồ sơ doanh nghiệp trong suốt năm, thay vì chỉ làm mới vào một thời điểm cố định. Cách làm này có thể giúp dữ liệu bớt nhanh lỗi thời, nhưng chất lượng tra cứu vẫn phụ thuộc độ đầy đủ và tính chính xác của hồ sơ do doanh nghiệp cung cấp.</p><p>Danh hiệu Top 10 và bản đồ doanh nghiệp là hai phần có mục đích khác nhau: danh hiệu ghi nhận các doanh nghiệp theo bộ tiêu chí của chương trình, còn bản đồ là công cụ tra cứu rộng hơn. Người dùng nên xem thông tin năng lực, sản phẩm, khách hàng tham chiếu và phạm vi dịch vụ trực tiếp với từng nhà cung cấp trước khi lựa chọn.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://en.vietnamplus.vn/vietnam-launches-2026-digital-technology-enterprise-map-covering-11-sectors-post355732.vnp">VietnamPlus – Vietnam launches 2026 digital technology enterprise map</a>. NEWS HUB biên tập lại, không sao chép nguyên văn.</p></blockquote>',
  thumbnail = 'seed_technology.jpg', status='published', is_featured=1
WHERE slug='sample-09-cong-nghe';

UPDATE articles SET
  category_id = (SELECT id FROM categories WHERE slug='kinh-doanh' LIMIT 1),
  title = 'Việt Nam và Nga thống nhất làm sâu sắc hợp tác trong lĩnh vực năng lượng',
  summary = 'Thông tin được công bố sau cuộc trao đổi bên lề APEC tại Thâm Quyến. Chưa có chi tiết công khai về dự án, vốn đầu tư hoặc hạng mục hợp tác cụ thể.',
  content = '<p>Việt Nam và Nga nhất trí làm sâu sắc hơn hợp tác trong lĩnh vực năng lượng sau cuộc trao đổi giữa lãnh đạo hai nước bên lề Hội nghị APEC tại Thâm Quyến ngày 19/11/2026. Reuters dẫn thông báo của Chính phủ Việt Nam về kết quả này.</p><p>Năng lượng là lĩnh vực có quan hệ hợp tác lâu năm giữa hai nước. Trong bối cảnh nhu cầu năng lượng, yêu cầu bảo đảm nguồn cung và chuyển dịch cơ cấu năng lượng cùng thay đổi, việc duy trì đối thoại có thể tạo nền tảng để hai bên xem xét những hướng hợp tác phù hợp với nhu cầu và điều kiện mới.</p><h2>Điểm còn chưa được công bố</h2><p>Thông tin hiện có không nêu tên dự án, quy mô vốn, công suất, thời hạn hoặc lĩnh vực kỹ thuật cụ thể. Do đó, chưa có cơ sở để kết luận hai bên đã ký một hợp đồng đầu tư hay chốt một dự án mới. Những nội dung đó cần được xác nhận bằng thông báo chính thức tiếp theo.</p><p>Với các dự án năng lượng có thời gian chuẩn bị dài, yếu tố quan trọng thường gồm hiệu quả kinh tế, công nghệ, an toàn, môi trường, cơ chế tài chính và khả năng kết nối với hệ thống hiện có. Việc cụ thể hóa thỏa thuận sẽ cần quá trình làm việc của cơ quan quản lý và doanh nghiệp hai nước.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://www.reuters.com/business/energy/vietnam-russia-leaders-agree-deepen-their-energy-cooperation-apec-2026-11-19/">Reuters – Vietnam, Russia leaders agree to deepen energy cooperation</a>. Ảnh đi kèm là ảnh minh họa nhà máy điện, không phải cơ sở thuộc thỏa thuận.</p></blockquote>',
  thumbnail = 'seed_energy.jpg', status='published', is_featured=0
WHERE slug='sample-33-doi-song';

UPDATE articles SET
  category_id = (SELECT id FROM categories WHERE slug='the-thao' LIMIT 1),
  title = 'U17 Việt Nam lần đầu dự World Cup: 48 đội tranh tài tại Qatar',
  summary = 'Giải diễn ra từ 19/11 đến 13/12/2026. Việt Nam là đại diện Đông Nam Á duy nhất ở vòng chung kết và mở màn bảng G bằng trận gặp Bỉ ngày 20/11.',
  content = '<p>Vòng chung kết FIFA U17 World Cup 2026 khởi tranh tại Qatar ngày 19/11 và kéo dài đến 13/12, với 48 đội tuyển tham dự. Theo VnExpress, đây là lần đầu U17 Việt Nam góp mặt ở giải đấu và đội cũng là đại diện duy nhất của Đông Nam Á tại kỳ này.</p><p>Việc mở rộng vòng chung kết lên 48 đội tạo thêm cơ hội cho nhiều nền bóng đá trẻ, đồng thời khiến lịch thi đấu và hành trình di chuyển của các đội trở nên đáng chú ý. Các trận đấu được tổ chức tại cụm sân thuộc Học viện Aspire ở Qatar; trận chung kết dự kiến diễn ra tại sân Ahmad bin Ali.</p><h2>Lịch thi đấu của U17 Việt Nam</h2><p>Đội tuyển Việt Nam nằm ở bảng G. Trận ra quân gặp Bỉ được lên lịch ngày 20/11; tiếp đó là New Zealand ngày 23/11 và Mali ngày 26/11. Đây đều là những đối thủ có kinh nghiệm ở sân chơi trẻ quốc tế, nên việc chuẩn bị thể lực, tâm lý và khả năng điều chỉnh chiến thuật sẽ rất quan trọng.</p><p>Lần đầu tham dự là cột mốc đáng ghi nhận với bóng đá trẻ Việt Nam. Kết quả từng trận sẽ quyết định cơ hội đi tiếp, nhưng giải đấu cũng là dịp để cầu thủ tích lũy kinh nghiệm trước những phong cách thi đấu khác nhau. Ảnh đi kèm chỉ minh họa một sân vận động bóng đá trẻ, không phải ảnh trận đấu tại Qatar.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://vnexpress.net/fifa-u17-world-cup-2026-khoi-tranh-hom-nay-5146326.html">VnExpress – FIFA U17 World Cup 2026 khởi tranh hôm nay</a>. Lịch thi đấu có thể thay đổi theo thông báo của ban tổ chức.</p></blockquote>',
  thumbnail = 'seed_sports.jpg', status='published', is_featured=0
WHERE slug='sample-13-the-thao';

UPDATE articles SET
  category_id = (SELECT id FROM categories WHERE slug='giao-duc' LIMIT 1),
  title = 'Hà Nội tuyên dương 99 thủ khoa tốt nghiệp đại học, học viện năm 2026',
  summary = 'Buổi lễ diễn ra tại Văn Miếu – Quốc Tử Giám tối 18/11. Thành phố nhấn mạnh chính sách thu hút, bồi dưỡng và tạo môi trường để người trẻ phát huy năng lực.',
  content = '<p>Tối 18/11/2026, Hà Nội tổ chức lễ tuyên dương 99 thủ khoa xuất sắc tốt nghiệp các trường đại học và học viện trên địa bàn. Buổi lễ diễn ra tại Văn Miếu – Quốc Tử Giám, nơi gắn với truyền thống học tập và tôn vinh hiền tài của Thăng Long – Hà Nội.</p><p>Theo Nhân Dân, chương trình được tổ chức thường niên hơn hai thập kỷ. Trong 24 năm, thành phố đã tuyên dương 2.450 thủ khoa; tên của những người được vinh danh được ghi vào Sổ vàng truyền thống của Thủ đô. Nhiều người sau đó tiếp tục làm việc trong cơ quan nhà nước, doanh nghiệp, nghiên cứu và các lĩnh vực chuyên môn.</p><h2>Từ tuyên dương đến cơ hội phát triển</h2><p>Lãnh đạo thành phố nhấn mạnh yêu cầu xây dựng đội ngũ nhân lực có chuyên môn, tầm nhìn và tinh thần cống hiến. Luật Thủ đô có hiệu lực từ tháng 7/2026 tạo cơ sở pháp lý cho các cơ chế thu hút, sử dụng nhân tài; thành phố cũng ban hành các kế hoạch về tuyển dụng, đào tạo và bố trí người có năng lực.</p><p>Vinh danh là bước ghi nhận thành quả học tập, nhưng để người trẻ gắn bó lâu dài cần có môi trường làm việc phù hợp, cơ hội nghiên cứu, cơ chế đánh giá minh bạch và con đường phát triển nghề nghiệp rõ ràng. Đây là phần việc cần được duy trì sau buổi lễ, không chỉ trong một dịp khen thưởng.</p><p>Ảnh minh họa đi kèm ghi lại sinh viên tốt nghiệp tại một trường đại học ở Hải Phòng; ảnh không phải tư liệu của buổi lễ tại Văn Miếu.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://en.nhandan.vn/ha-noi-honours-99-outstanding-university-graduates-post169358.html">Nhân Dân – Ha Noi honours 99 outstanding university graduates</a>. NEWS HUB biên tập lại bằng lời riêng.</p></blockquote>',
  thumbnail = 'seed_education.jpg', status='published', is_featured=0
WHERE slug='sample-21-giao-duc';

SELECT id, title, status, is_featured, published_at, thumbnail
FROM articles
WHERE slug IN (
  'sample-01-thoi-su','sample-05-the-gioi','sample-07-tai-chinh','sample-09-cong-nghe',
  'sample-13-the-thao','sample-21-giao-duc','sample-33-doi-song','sample-03-moi-truong'
)
ORDER BY id;
COMMIT;
